            const SizedBox(width: 8),
            buildCircleArrowButton(
              Icons.chevron_right,
              navNotifier.canGoForward,
              navNotifier.canGoForward
                  ? () => navNotifier.navigateForward()
                  : null,
            ),
            const SizedBox(width: 16),

            // Search Bar (Desktop)
