  Widget _buildPlayerBar(
    BuildContext context,
    WidgetRef ref,
    ZephyrPlayerState state,
    PlayerNotifier notifier,
  ) {
    final isMobile = MediaQuery.of(context).size.width < 700;

    if (state.currentTrack == null) {
      return Container(
        height: isMobile ? 50 : 90,
        color: ZephyrColors.bgCard,
        alignment: Alignment.center,
        child: Text(
          'Select a track to start listening',
          style: TextStyle(
            color: ZephyrColors.textDim,
            fontSize: isMobile ? 12 : 14,
          ),
        ),
      );
    }

    final track = state.currentTrack!;
    final ownerName = state.activeDeviceName?.trim();
    final showRemoteOwner =
        !state.isPlayerDevice && ownerName != null && ownerName.isNotEmpty;
    ref.watch(libraryProvider);
    final libraryNotifier = ref.read(libraryProvider.notifier);
    final isFav = libraryNotifier.isFavorite(track.videoId, title: track.title, artists: track.artists);
    final navState = ref.watch(navigationProvider);
    final navNotifier = ref.read(navigationProvider.notifier);

    if (isMobile) {
      final double progress = state.effectiveDuration.inMilliseconds > 0
          ? (state.position.inMilliseconds /
                    state.effectiveDuration.inMilliseconds)
                .clamp(0.0, 1.0)
          : 0.0;

      final mobileBar = Container(
        color: ZephyrColors.bgCard,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            LayoutBuilder(
              builder: (ctx, constraints) {
                final width = constraints.maxWidth;
                final thumbX = (width * progress).clamp(0.0, width);

                return GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTapDown: (details) {
                    if (width > 0 && state.effectiveDuration > Duration.zero) {
                      final frac = (details.localPosition.dx / width).clamp(
                        0.0,
                        1.0,
                      );
                      notifier.seek(state.effectiveDuration * frac);
                    }
                  },
                  onHorizontalDragUpdate: (details) {
                    if (width > 0 && state.effectiveDuration > Duration.zero) {
                      final frac = (details.localPosition.dx / width).clamp(
                        0.0,
                        1.0,
                      );
                      notifier.seek(state.effectiveDuration * frac);
                    }
                  },
                  child: Container(
                    height: 14,
                    color: Colors.transparent,
                    child: Stack(
                      alignment: Alignment.centerLeft,
                      children: [
                        // Background Track
                        Container(
                          height: 3,
                          width: double.infinity,
                          color: ZephyrColors.bgLight,
                        ),
                        // Active Progress Fill
                        FractionallySizedBox(
                          widthFactor: progress,
                          child: Container(
                            height: 3,
                            color: ZephyrColors.primary,
                          ),
                        ),
                        // Draggable Solid Amber Thumb Circle
                        Positioned(
                          left: (thumbX - 6).clamp(
                            0.0,
                            width > 12 ? width - 12 : 0.0,
                          ),
                          child: Container(
                            width: 12,
                            height: 12,
                            decoration: BoxDecoration(
                              color: ZephyrColors.primary,
                              shape: BoxShape.circle,
                              boxShadow: [
                                BoxShadow(
                                  color: ZephyrColors.primary.withValues(
                                    alpha: 0.5,
                                  ),
                                  blurRadius: 4,
                                ),
                              ],
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
            InkWell(
              onTap: () {
                if (navState.currentScreen.type == ScreenType.lyrics) {
                  navNotifier.navigateBack();
                } else {
                  navNotifier.navigateTo(
                    const ScreenState(type: ScreenType.lyrics),
                  );
                }
              },
              child: Container(
                height: 64,
                padding: const EdgeInsets.symmetric(horizontal: 12),
                child: Row(
                  children: [
                    CoverImage(
                      videoId: track.videoId,
                      coverUrl: track.coverUrl,
                      size: 44,
                      borderRadius: 6,
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            track.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w600,
                              color: ZephyrColors.text,
                            ),
                          ),
                          const SizedBox(height: 2),
                          Row(
                            children: [
                              if (showRemoteOwner) ...[
                                const Icon(
                                  Icons.speaker_rounded,
                                  size: 12,
                                  color: ZephyrColors.primary,
                                ),
                                const SizedBox(width: 3),
                                Flexible(
                                  child: Tooltip(
                                    message: 'Playing on $ownerName',
                                    child: Text(
                                      ownerName,
                                      maxLines: 1,
                                      overflow: TextOverflow.ellipsis,
                                      style: const TextStyle(
                                        fontSize: 11,
                                        color: ZephyrColors.primary,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 4),
                                const Text(
                                  '•',
                                  style: TextStyle(
                                    fontSize: 10,
                                    color: ZephyrColors.textDim,
                                  ),
                                ),
                                const SizedBox(width: 4),
                              ],
                              Flexible(
                                child: Text(
                                  track.artists.join(', '),
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    fontSize: 11,
                                    color: ZephyrColors.textDim,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                    FavoriteButton(
                      isFavorite: isFav,
                      size: 20,
                      onTap: () => libraryNotifier.toggleFavorite(track),
                    ),
                    IconButton(
                      icon: Icon(
                        Icons.devices_rounded,
                        color: !state.isPlayerDevice
                            ? ZephyrColors.primary
                            : ZephyrColors.textDim,
                        size: 22,
                      ),
                      tooltip: 'Connect to a device',
                      onPressed: () => DevicesModal.show(context),
                    ),
                    if (state.isLoading)
                      const SizedBox(
                        width: 24,
                        height: 24,
                        child: CircularProgressIndicator(
                          strokeWidth: 2.5,
                          valueColor: AlwaysStoppedAnimation<Color>(
                            ZephyrColors.primary,
                          ),
                        ),
                      )
                    else
                      IconButton(
                        icon: Icon(
                          state.isPlaying ? Icons.pause : Icons.play_arrow,
                          color: ZephyrColors.text,
                          size: 28,
                        ),
                        onPressed: () => notifier.togglePlayPause(),
                      ),
                  ],
                ),
              ),
            ),
          ],
        ),
      );

      return Dismissible(
        key: ValueKey('mobile_bar_${track.videoId}'),
        direction: DismissDirection.horizontal,
        confirmDismiss: (direction) async {
          if (direction == DismissDirection.endToStart) {
            notifier.playNext();
            HapticFeedback.lightImpact();
          } else if (direction == DismissDirection.startToEnd) {
            notifier.playPrevious();
            HapticFeedback.lightImpact();
          }
          return false;
        },
        background: Container(
          alignment: Alignment.centerLeft,
          padding: const EdgeInsets.only(left: 20),
          color: ZephyrColors.bgCard,
          child: const Icon(
            Icons.skip_previous,
            color: ZephyrColors.primary,
            size: 24,
          ),
        ),
        secondaryBackground: Container(
          alignment: Alignment.centerRight,
          padding: const EdgeInsets.only(right: 20),
          color: ZephyrColors.bgCard,
          child: const Icon(
            Icons.skip_next,
            color: ZephyrColors.primary,
            size: 24,
          ),
        ),
        child: mobileBar,
      );
    }

    return Container(
      height: 84,
      color: ZephyrColors.bgCard,
      padding: const EdgeInsets.symmetric(horizontal: 32),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          // Left: Cover + Metadata + Like Button (Anchored fixed width!)
          SizedBox(
            width: 280,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                InkWell(
                  onTap: () {
                    if (navState.currentScreen.type == ScreenType.lyrics) {
                      navNotifier.navigateBack();
                    } else {
                      navNotifier.navigateTo(
                        const ScreenState(type: ScreenType.lyrics),
                      );
                    }
                  },
                  borderRadius: BorderRadius.circular(6),
                  child: CoverImage(
                    videoId: track.videoId,
                    coverUrl: track.coverUrl,
                    size: 56,
                    borderRadius: 6,
                  ),
                ),
                const SizedBox(width: 12),
                Flexible(
                  child: GestureDetector(
                    onSecondaryTapDown: (details) {
                      showPlayerSongContextMenu(
                        context,
                        ref,
                        track,
                        details.globalPosition,
                      );
                    },
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        InkWell(
                          onTap: () {
                            if (navState.currentScreen.type ==
                                ScreenType.lyrics) {
                              navNotifier.navigateBack();
                            } else {
                              navNotifier.navigateTo(
                                const ScreenState(type: ScreenType.lyrics),
                              );
                            }
                          },
                          child: Text(
                            track.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w500,
                              color: ZephyrColors.text,
                            ),
                          ),
                        ),
                        const SizedBox(height: 2),
                        Row(
                          children: [
                            Flexible(
                              child: ArtistLinks(
                                track: track,
                                style: const TextStyle(
                                  fontSize: 12,
                                  color: ZephyrColors.textDim,
                                ),
                              ),
                            ),
                            if (showRemoteOwner) ...[
                              const SizedBox(width: 6),
                              Flexible(
                                child: Tooltip(
                                  message: 'Playing on $ownerName',
                                  child: Text(
                                    'Playing on $ownerName',
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      fontSize: 11,
