      IconData icon,
      bool enabled,
      VoidCallback? onTap,
    ) {
      return Container(
        width: 32,
        height: 32,
        decoration: BoxDecoration(
          color: Colors.black.withValues(alpha: 0.35),
          shape: BoxShape.circle,
        ),
